# %%
def _show_two_green_packs() -> None:
    honest = audit_repair(PACK, SUITE,
                          plan_repairs(PACK, inspect_pack(run_suite(PACK, SUITE))))
    silent = audit_repair(PACK, SUITE, SILENT_PLAN)
    for name, result in (("REPAIRED", honest), ("SILENCED", silent)):
        report = inspection_report(result)
        print(f"{name}  {report['green_after']}/{report['checks']} checks green · "
              f"evidence +{report['evidence']['added']} "
              f"~{report['evidence']['mutated']} -{report['evidence']['removed']} · "
              f"suite unchanged {report['suite_unchanged']} · "
              f"{len(report['unsupported'])} numbers that do not reproduce")
        for row in report["findings"]:
            print(f"   {row['verdict']:9s} {row['finding_id']:58s} "
                  f"{row['reasons'][0] if row['reasons'] else ''}")
        print(f"   -> {report['verdict']}\n")


