# %% [markdown]
# ## What you built, and what the programme leaves you with
#
# An inspection that runs the nine modules' tools over somebody else's pack and reports a
# check nobody ran as the worst finding on the page; a repair expressed as operations against
# the evidence rather than as edits to a file; and the audit that decides whether the repair
# was a repair — three independent measurements, two of which never trust a word the repairer
# wrote down.
#
# That audit is the only thing in this programme that cannot be borrowed from a template. A
# conformity pack is a promise that somebody will check, and the whole apparatus — the hash
# chain in module 1, the typed sources in module 3, the retained evaluation split in module 6,
# the baseline sealed before the period it judges in module 7, the assessment ledger in module
# 8 — exists for one purpose: so that a year from now, somebody who was not there can tell a
# number that was measured from a number that was needed.
#
# **Again, and finally: this is engineering, not legal advice.**

# %%
_MARKS = {"passed": "✅", "failed": "❌", "not started": "⏳"}


def _progress_board() -> None:
    """One line per exercise, from the latest run of its check, then the tally."""
    width = max(len(", ".join(funcs)) for funcs in _EXERCISES.values())
    print(f"progress board: your {len(_EXERCISES)} exercises. The pack's own checks are "
          "not on it.")
    for label, funcs in _EXERCISES.items():
        state = _STATUS.get(label, "not started")
        print(f"  {_MARKS[state]} {label:<12} {', '.join(funcs):<{width}}  {state}")
    done = sum(_STATUS.get(label) == "passed" for label in _EXERCISES)
    print(f"\n{done} of {len(_EXERCISES)} exercises complete")
    failing = [label for label in _EXERCISES if _STATUS.get(label) == "failed"]
    if failing:
        print("failing right now: " + ", ".join(failing) + ". Each one printed what went "
              "wrong in its own cell above, and every exercise has hints you can open.")
    elif done < len(_EXERCISES):
        print("work top to bottom: every exercise has hints you can open above its code,\n"
              "and a check that is waiting on an earlier exercise says which one.")


# Your progress board. Every check is re-run here, quietly, against your code as it stands
# now — each one already printed its feedback in its own cell above — so the board is
# current even if you edited an exercise and did not re-run its check.
if __name__ == "__main__":
    with contextlib.redirect_stdout(io.StringIO()):
        for _name, _check in (("exercise 1", _check_run_suite),
                              ("exercise 2", _check_inspect_pack),
                              ("exercise 3", _check_evidence_delta),
                              ("exercise 4", _check_suite_delta),
                              ("exercise 5", _check_unsupported_values),
                              ("exercise 6", _check_silencing_audit),
                              ("exercise 7", _check_plan_repairs),
                              ("exercise 8", _check_inspection_report)):
            _try(_name, _check, needs=_UPSTREAM.get(_name, ()))
    _progress_board()
    # A stub you have not reached yet is not a failure. A check that ran and came back wrong
    # is: in a script or under CI it ends this run non-zero, rather than letting a green exit
    # code paper over it. Inside a notebook kernel the board above has already said so, in a
    # line rather than a traceback at the foot of the page.
    if _FAILED_CHECKS and "ipykernel" not in sys.modules:
        raise SystemExit("checks failed: " + ", ".join(dict.fromkeys(_FAILED_CHECKS)))
